  String fa(String s){ return s.replace("0","۰").replace("1","۱").replace("2","۲").replace("3","۳").replace("4","۴").replace("5","۵").replace("6","۶").replace("7","۷").replace("8","۸").replace("9","۹"); }
  TextView tv(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.WHITE);v.setGravity(Gravity.CENTER);v.setTypeface(Typeface.create("sans",Typeface.BOLD));v.setPadding(16,12,16,12);return v;}
  GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{c,Color.rgb(Math.min(255,c+35),Math.min(255,c+45),Math.min(255,c+75))});g.setCornerRadius(r);g.setStroke(2,Color.argb(180,255,193,7));return g;}
  Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(17);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setGravity(Gravity.CENTER);b.setPadding(12,0,12,0);b.setBackground(bg(Color.rgb(17,76,155),30));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,64);p.setMargins(10,7,10,7);b.setLayoutParams(p);return b;}
  void base(int color){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setGravity(Gravity.CENTER_HORIZONTAL);root.setPadding(18,12,18,18);root.setBackground(bg(color,0));setContentView(root);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);}
  void showHome(){base(Color.rgb(7,18,55));TextView brand=tv("👑  چالش دانا",35);brand.setTextColor(Color.rgb(255,205,70));root.addView(brand,new LinearLayout.LayoutParams(-1,82));root.addView(tv("فکر کن • حدس بزن • برنده شو",17));TextView info=tv("بیش از "+bank.size()+" سؤال متنوع • تصویرهای متغیر • مراحل بی‌پایان",14);info.setTextColor(Color.LTGRAY);root.addView(info);Button start=btn("▶  شروع چالش");start.setBackground(bg(Color.rgb(206,139,18),30));start.setTextColor(Color.rgb(20,20,20));start.setOnClickListener(v->startGame());root.addView(start);String[] menu={"🌍  دسته‌بندی‌ها","🏆  رکورد و امتیاز","✨  چالش ویژه"};for(String s:menu){Button m=btn(s);m.setOnClickListener(v->Toast.makeText(this,"این بخش در نسخه‌های بعدی کامل‌تر می‌شود.",Toast.LENGTH_SHORT).show());root.addView(m);}Space sp=new Space(this);root.addView(sp,new LinearLayout.LayoutParams(1,0,1));root.addView(tv("دانش، قدرت واقعی است ...",14));}
  void startGame(){index=0;score=0;coin=50;Collections.shuffle(bank,rnd);showQuestion();}
  void showQuestion(){Q q=bank.get(index%bank.size());base(backs[index%backs.length]);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);coins=tv(fa("🪙 "+coin),16);coins.setGravity(Gravity.RIGHT);root.addView(coins,p);progress=tv(fa("مرحله "+(index+1)+" از "+bank.size()),14);progress.setTextColor(Color.rgb(120,230,255));root.addView(progress,p);category=tv("◆ "+q.cat+" ◆",15);category.setTextColor(Color.rgb(255,210,75));root.addView(category,p);questionImage=new ImageView(this);questionImage.setImageResource(q.img);questionImage.setScaleType(ImageView.ScaleType.CENTER_INSIDE);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,185);ip.setMargins(8,4,8,5);root.addView(questionImage,ip);question=tv(q.q,20);question.setTextColor(Color.WHITE);question.setBackground(bg(Color.rgb(10,40,95),28));root.addView(question,new LinearLayout.LayoutParams(-1,130));answersBox=new LinearLayout(this);answersBox.setOrientation(LinearLayout.VERTICAL);answersBox.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.addView(answersBox,new LinearLayout.LayoutParams(-1,-2));String[] opts={q.a,q.b,q.c,q.d};for(int i=0;i<4;i++){final int n=i;Button b=btn(fa((i+1)+"  ")+opts[i]);b.setOnClickListener(v->answer(n,b,q));answersBox.addView(b);}}
  void answer(int n,Button chosen,Q q){for(int i=0;i<answersBox.getChildCount();i++)answersBox.getChildAt(i).setEnabled(false);if(n==q.ans){score+=10;coin+=5;chosen.setBackground(bg(Color.rgb(10,145,95),30));chosen.setText("✓  "+chosen.getText()+"   +10");}else{coin=Math.max(0,coin-5);chosen.setBackground(bg(Color.rgb(150,35,55),30));chosen.setText("✕  "+chosen.getText());Button correct=(Button)answersBox.getChildAt(q.ans);correct.setBackground(bg(Color.rgb(10,145,95),30));correct.setText("✓  "+correct.getText());}new Handler().postDelayed(()->{index++;if(index<bank.size())showQuestion();else showResult();},1800);}
  void showResult(){base(Color.rgb(12,18,52));root.addView(tv("🏆  چالش تمام شد",30));root.addView(tv(fa("امتیاز شما: "+score),24));root.addView(tv(fa("🪙 سکه: "+coin),20));root.addView(tv("شما "+bank.size()+" سؤال را پشت سر گذاشتید!",15));Button again=btn("✨ شروع دوباره");again.setOnClickListener(v->startGame());root.addView(again);Button home=btn("⌂ بازگشت به خانه");home.setOnClickListener(v->showHome());root.addView(home);}
